/**
 * Sign-in, accounts and tokens. One per app.
 */
public protocol AuthManagerProtocol: AnyObject, Sendable {
    
    /**
     * A fresh access token for the active account (refreshes when close to expiry).
     */
    func accessToken() async throws  -> String?
    
    func accounts() throws  -> [AccountInfo]
    
    func activeAccount() throws  -> AccountInfo?
    
    func addListener(listener: AuthListener) 
    
    /**
     * An API client bound to one account (`user_id`, or the active account when `None`): it
     * keeps acting as that account after an account switch, and refreshes on 401. Create a new
     * client after switching accounts.
     */
    func apiClient(config: ApiClientConfig, userId: String?) throws  -> ApiClient
    
    /**
     * Starts a device-code sign-in. Throws `Unsupported` until the auth server ships RFC 8628.
     */
    func beginDeviceLogin() async throws  -> DeviceLogin
    
    /**
     * Step 1 of browser sign-in.
     */
    func beginLogin() throws  -> LoginRequest
    
    /**
     * Step 1 with an explicit `prompt` (`Silent` re-authorizes without UI, `Login` adds an account).
     */
    func beginLoginWithPrompt(prompt: LoginPrompt) throws  -> LoginRequest
    
    /**
     * Step 1 for desktop apps that receive the code on a loopback listener (RFC 8252 §7.3):
     * `redirect_uri` is `http://127.0.0.1:{port}/…` with the port the listener got. Pass the
     * request the listener received, as a full URL with that same origin, to `complete_login`.
     */
    func beginLoginWithRedirect(prompt: LoginPrompt, redirectUri: String) throws  -> LoginRequest
    
    /**
     * Polls until approved; throws `Cancelled` if denied or cancelled.
     */
    func completeDeviceLogin(login: DeviceLogin) async throws  -> AccountInfo
    
    /**
     * Step 2: pass the full redirect URL the app received.
     */
    func completeLogin(redirectUrl: String) async throws  -> AccountInfo
    
    func setActiveChannel(channelId: String?) throws 
    
    /**
     * Removes the account from this device at once, then revokes its refresh token on the
     * server in the background (best effort; a failure never undoes the sign-out). Use
     * `sign_out_and_revoke` to wait for the revocation.
     */
    func signOut(userId: String) throws 
    
    /**
     * Signs out on this device, then waits (up to 10 s) for the server to revoke the refresh
     * token. Never fails because of the revocation.
     */
    func signOutAndRevoke(userId: String) async throws 
    
    func switchAccount(userId: String) throws  -> AccountInfo
    
    /**
     * A valid access token for the given account, even when another account is active.
     * Set `force_refresh` to refresh after a 401. Returns `None` if the account is missing or
     * needs sign-in again.
     */
    func tokenForAccount(userId: String, forceRefresh: Bool) async throws  -> String?
    
}
