            writeInt(&buf, Int32(5))
            FfiConverterDouble.write(rate, into: &buf)
            
        
        case let .setQualityCap(cap):
            writeInt(&buf, Int32(6))
            FfiConverterTypePlayerQualityCap.write(cap, into: &buf)
            
        
        case .stop:
